<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import type { BookSource } from '../../api/sources';
import AppButton from '../../ui/components/AppButton.vue';
export default defineComponent({name:'SourceEditorDialog',components:{AppButton},props:{source:{type:Object as PropType<BookSource>,required:true},busy:Boolean,serverError:{type:String,default:''}},emits:['save','close'],data(){return{raw:JSON.stringify(this.source,null,2),error:''}},methods:{submit(){try{const parsed=JSON.parse(this.raw) as BookSource;if(!parsed||typeof parsed!=='object')throw new Error(this.$t('sources.editor.objectRequired'));if(typeof parsed.bookSourceName!=='string'||!parsed.bookSourceName.trim())throw new Error(this.$t('sources.editor.nameRequired'));this.error='';this.$emit('save',{...parsed,bookSourceUrl:this.source.bookSourceUrl})}catch(cause){this.error=cause instanceof Error?cause.message:this.$t('sources.editor.invalid')}}}});
</script>
<template><div class="overlay" @click.self="$emit('close')" @keydown.esc="$emit('close')"><section class="dialog" role="dialog" aria-modal="true" :aria-label="$t('sources.editor.title')"><header><div><p class="eyebrow">{{ $t('sources.editor.eyebrow') }}</p><h2>{{ source.bookSourceName }}</h2><p>{{ source.bookSourceUrl }}</p></div><AppButton variant="quiet" :disabled="busy" @click="$emit('close')">{{ $t('sources.close') }}</AppButton></header><p class="warning">{{ $t('sources.editor.warning') }}</p><label><span>{{ $t('sources.editor.json') }}</span><textarea v-model="raw" spellcheck="false" :disabled="busy" /></label><p v-if="error||serverError" class="error" role="alert">{{ error||serverError }}</p><footer><AppButton variant="secondary" :disabled="busy" @click="$emit('close')">{{ $t('sources.cancel') }}</AppButton><AppButton :busy="busy" @click="submit">{{ $t('sources.editor.save') }}</AppButton></footer></section></div></template>
<style scoped>.overlay{position:fixed;z-index:90;inset:0;display:flex;align-items:center;justify-content:center;padding:1rem;background:rgb(0 0 0/.42)}.dialog{width:min(58rem,100%);height:min(50rem,92dvh);display:grid;grid-template-rows:auto auto minmax(0,1fr) auto auto;gap:.8rem;padding:1rem;border-radius:var(--radius-lg);background:var(--color-paper-raised);color:var(--color-ink)}header,footer{display:flex;justify-content:space-between;align-items:center;gap:1rem}h2,p{margin:0}h2{font:700 1.25rem var(--font-literary)}header p{color:var(--color-ink-muted);overflow-wrap:anywhere}.eyebrow{color:var(--color-warm)!important;font-size:.7rem;font-weight:800;letter-spacing:.1em;text-transform:uppercase}.warning{padding:.65rem;border:1px solid color-mix(in srgb,var(--color-warm) 45%,var(--color-border));border-radius:var(--radius-md);background:#fff8e9;color:var(--color-ink-muted);font-size:.82rem}label{min-height:0;display:grid;grid-template-rows:auto minmax(0,1fr);gap:.35rem}label span{font-size:.78rem;font-weight:700}textarea{min-height:0;resize:none;border:1px solid var(--color-border);border-radius:var(--radius-md);padding:.75rem;background:#fbfaf5;color:var(--color-ink);font:400 .78rem/1.55 var(--font-mono,monospace);tab-size:2}.error{color:var(--color-danger)}footer{justify-content:flex-end}@media(max-width:34rem){.overlay{padding:0;align-items:flex-end}.dialog{height:94dvh;border-radius:var(--radius-lg) var(--radius-lg) 0 0}}</style>